from lib import *
S = SS('s2')
steps = [
    step("同一个只下载一个页面的 spider,三种启动方式。默认:AsyncCrawlerProcess + AsyncioSelectorReactor,事件循环是 asyncio 自带的 _UnixSelectorEventLoop(ASYNCIO_EVENT_LOOP 默认 None,TWISTED_REACTOR_ENABLED 默认 True)。显式把 TWISTED_REACTOR 设成 SelectReactor:改用旧的 CrawlerProcess,reactor 是 selectreactor.SelectReactor。第三种(这个版本里有):TWISTED_REACTOR_ENABLED=False,日志是 “Not using a Twisted reactor”,下载处理器换成 AiohttpDownloadHandler,并警告 “experimental and is not recommended for production use”(http 和 https 各打印一次)。", t=tl(S(1)), mark=lidx(S(1), 'AsyncioSelectorReactor', 'SelectReactor', 'Not using a Twisted reactor'), done=lidx(S(1), 'Using AsyncCrawlerProcess', 'Using CrawlerProcess', 'Aiohttp', '默认值'), kv=KV([['默认', 'AsyncCrawlerProcess + AsyncioSelectorReactor'], ['显式 SelectReactor', '回到 CrawlerProcess'], ['TWISTED_REACTOR_ENABLED=False', '没有 reactor,aiohttp 下载(实验性)'], ['事件循环默认', '_UnixSelectorEventLoop']], ['默认'])),
    step("单线程同时处理 100 个慢请求:100 个页面、服务器每个延迟 0.5 s、CONCURRENT_REQUESTS=100。默认 asyncio reactor 总耗时 0.62 s,SelectReactor 0.67 s,无 reactor 0.59 s;服务器那边同时在处理的请求峰值都是 100,所有回调都在 MainThread 里运行。进程里的线程数最大是 2(两种 reactor)和 1(无 reactor)——多出的那个线程我没有去查是什么。100 个请求 0.5 s 的延迟,总耗时只比 0.5 s 多 0.1 s,说明下载不是一个请求一个线程。", t=tl(S(2)), mark=lidx(S(2), 'asyncio reactor', 'SelectReactor', '无 reactor'), done=lidx(S(2), '方式'), b=bars([['asyncio reactor', 0.62, '0.62 s'], ['SelectReactor', 0.67, '0.67 s'], ['无 reactor', 0.59, '0.59 s']], 0.7, mark=[2], done=[0, 1]), kv=KV([['服务器并发峰值', '100(三种都是)'], ['回调线程', '都是 MainThread'], ['最大线程数', '2 / 2 / 1'], ['理想值', '0.5 s + 一点开销']], ['服务器并发峰值'])),
    step("同步阻塞会拖住所有请求,因为回调和网络 I/O 在同一个线程里:20 个页面、服务器延迟 0.3 s、并发 20。回调什么也不做 0.34 s;回调里 time.sleep(0.1) 总耗时 2.39 s(理想值 0.3 + 20×0.1 = 2.3);并发改成 1 则 8.21 s(20×(0.3+0.1) = 8);把回调改成 async def + await asyncio.sleep(0.1) 只要 0.43 s(0.3 + 0.1)。同样是“等 0.1 s”,同步版把 20 个请求串行化了,异步版并发等待。", t=tl(S(3)), mark=lidx(S(3), 'time.sleep(0.1)  ', '并发改成 1', 'await asyncio.sleep'), done=lidx(S(3), '回调什么都不做'), b=bars([['什么都不做', 0.34, '0.34 s'], ['async + await', 0.43, '0.43 s'], ['sleep(0.1)', 2.39, '2.39 s'], ['sleep + 并发 1', 8.21, '8.21 s']], 8.21, mark=[2, 3], done=[0, 1]), kv=KV([['阻塞回调', '拖慢整个进程,总耗时 2.39 s'], ['并发 1 的阻塞回调', '8.21 s'], ['async 回调', '0.43 s'], ['原因', '回调与 I/O 共用一个线程']], ['阻塞回调'])),
    step("async def 回调里 await asyncio.sleep 依赖 asyncio:默认的 asyncio reactor 下 20 个回调都正常(总耗时 0.45 s,spider_exceptions/count=0);SelectReactor 下 20 个回调全部抛 RuntimeError: no running event loop(spider_exceptions/count=20,请求本身仍然下载成功,response_received_count=21);无 reactor 模式用 asyncio 事件循环,同样正常(0.43 s)。也就是说想用 asyncio 的库,TWISTED_REACTOR 要么保持默认,要么干脆不用 reactor。", t=tl(S(4)), mark=lidx(S(4), 'SelectReactor', 'no running event loop'), done=lidx(S(4), 'asyncio reactor(默认)', '无 reactor'), kv=KV([['asyncio reactor', '0 个异常,0.45 s'], ['SelectReactor', '20 个 RuntimeError: no running event loop'], ['无 reactor', '0 个异常,0.43 s']], ['SelectReactor'])),
    step("事件循环可以换:ASYNCIO_EVENT_LOOP=uvloop.Loop(uvloop 0.23.0)。300 个零延迟请求(并发 100),默认循环 3 次分别 0.302、0.299、0.335 s,中位数 0.302 s;uvloop 3 次分别 0.275、0.277、0.271 s,中位数 0.275 s,约快 9%,日志里 “Using asyncio event loop” 变成 uvloop.Loop。差距不大,因为这里的瓶颈有一部分是本机的 Python 测试服务器。", t=tl(S(5)), mark=lidx(S(5), 'uvloop.Loop'), done=lidx(S(5), '默认事件循环'), b=bars([['默认循环', 0.302, '0.302 s'], ['uvloop', 0.275, '0.275 s']], 0.31, mark=[1], done=[0]), kv=KV([['默认', '中位数 0.302 s'], ['uvloop', '中位数 0.275 s'], ['差距', '约 9%']], ['uvloop'])),
]
